// static
bool UnionTraits<::ax::android::mojom::AccessibilityWindowKey::DataView, ::ax::android::mojom::AccessibilityWindowKeyPtr>::Read(
    ::ax::android::mojom::AccessibilityWindowKey::DataView input,
    ::ax::android::mojom::AccessibilityWindowKeyPtr* output) {
  using UnionType = ::ax::android::mojom::AccessibilityWindowKey;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kWindowId: {
      *output = UnionType::NewWindowId(input.window_id());
      break;
    }
    case Tag::kTaskId: {
      *output = UnionType::NewTaskId(input.task_id());
      break;
    }
    default:

      return false;
  }
  return true;
}

